 "content": "def transform(grid):
    """Extend matching diagonal pairs through background cells until blockers."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    pairs = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color:
                    pairs.append((r, c, nr, nc, dr, dc, color))

    def shared_other_neighbor(r1, c1, r2, c2, color):
        neighbors = set()
        for r, c in ((r1, c1), (r2, c2)):
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w:
                    v = grid[rr][cc]
                    if v != background and v != color:
                        neighbors.add(v)
        return neighbors

    for r1, c1, r2, c2, dr, dc, color in pairs:
        # If both endpoints are joined to the same other-colored feature,
        # they are part of a compact multicolor motif rather than an extension line.
        if shared_other_neighbor(r1, c1, r2, c2, color):
            common = set()
            endpoint_neighbors = []
            for r, c in ((r1, c1), (r2, c2)):
                vals = set()
                for ar, ac in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    rr, cc = r + ar, c + ac
                    if 0 <= rr < h and 0 <= cc < w:
                        v = grid[rr][cc]
                        if v != background and v != color:
                            vals.add(v)
                endpoint_neighbors.append(vals)
            common = endpoint_neighbors[0] & endpoint_neighbors[1]
            if common:
                continue

        for sr, sc, step_r, step_c in (
            (r1, c1, -dr, -dc),
            (r2, c2, dr, dc),
        ):
            rr, cc = sr, sc
            while 0 <= rr + step_r < h and 0 <= cc + step_c < w:
                rr += step_r
                cc += step_c
                if out[rr][cc] != background:
                    break
                out[rr][cc] = color
    return out

if __name__ == '__main__':
    # Pair 1 exact verification.
    d1 = [[6] * 15 for _ in range(25)]
    d1[15][0], d1[15][1] = 9, 5
