    e2[9][15] = 0
    assert transform(d2) == e2

    # Current test input: the 5 diagonal extends toward the upper right.
    test = [[9] * 18 for _ in range(7)]
    test[3][2] = 5
    test[4][0], test[4][1] = 4, 5
